/**
 * Business identifier map: which field of which submodule is generated by the
 * backend, and with what prefix.
 *
 *   key: [field, prefix, { year }]
 *
 * `year: false` marks long-lived master records (farmers, employees, items...)
 * whose codes never reset; everything else is numbered per financial year, e.g.
 * `PO-2627-00012`. Admins can override prefix / padding / suffix / year per
 * submodule through Settings > Document Numbering (rule code = submodule key).
 *
 * Configuration-style codes (departments, roles, tax rates, GL accounts...) and
 * natural identifiers (vehicle registration plates) are intentionally NOT here:
 * those are chosen by people, not generated.
 */
const MASTER = { year: false };

const NUMBERING = {
  // Master records
  item: ['code', 'ITM', MASTER],
  supplier: ['code', 'SUP', MASTER],
  customer: ['code', 'CUS', MASTER],
  transporter: ['code', 'TRN', MASTER],
  farmer: ['code', 'FRM', MASTER],
  employee: ['employeeCode', 'EMP', MASTER],
  equipment: ['code', 'EQP', MASTER],
  assetRegister: ['assetCode', 'AST', MASTER],
  caneRate: ['rateCode', 'CRT', MASTER],

  // Cane management
  caneContract: ['contractNo', 'CNT'],
  caneIndent: ['indentNo', 'IND'],
  caneGateEntry: ['gatePassNo', 'GP'],
  caneWeighment: ['slipNo', 'WS'],
  caneQuality: ['sampleNo', 'CQ'],
  canePayment: ['paymentNo', 'CPY'],
  harvestingSchedule: ['scheduleNo', 'HRV'],

  // Production
  crushingPlan: ['planNo', 'CRP'],
  shiftProduction: ['entryNo', 'SPR'],
  juiceAnalysis: ['sampleNo', 'JAN'],
  boilingHouseLog: ['logNo', 'BHL'],
  sugarBagging: ['baggingNo', 'BAG'],
  byProduct: ['entryNo', 'BYP'],
  powerGeneration: ['entryNo', 'PWR'],
  plantDowntime: ['entryNo', 'DWN'],

  // Procurement
  purchaseRequisition: ['requisitionNo', 'PR'],
  purchaseEnquiry: ['enquiryNo', 'PEQ'],
  quotation: ['quotationNo', 'QTN'],
  purchaseOrder: ['poNo', 'PO'],
  goodsReceipt: ['grnNo', 'GRN'],
  qualityInspection: ['inspectionNo', 'QI'],
  purchaseReturn: ['returnNo', 'PRT'],

  // Stores
  stockLedger: ['entryNo', 'SL'],
  materialIssue: ['issueNo', 'MI'],
  stockTransfer: ['transferNo', 'STF'],
  stockAdjustment: ['adjustmentNo', 'ADJ'],
  physicalVerification: ['verificationNo', 'PVR'],
  stockValuation: ['valuationNo', 'SVL'],

  // Sales
  salesEnquiry: ['enquiryNo', 'SEQ'],
  salesOrder: ['orderNo', 'SO'],
  salesReleaseOrder: ['releaseNo', 'SRO'],
  dispatch: ['dispatchNo', 'DSP'],
  salesInvoice: ['invoiceNo', 'INV'],
  salesReturn: ['returnNo', 'SRT'],
  customerReceipt: ['receiptNo', 'RCT'],
  customerLedger: ['entryNo', 'CL'],

  // Quality
  labTest: ['testNo', 'LT'],
  sampleCollection: ['sampleNo', 'SMP'],
  certificateOfAnalysis: ['certificateNo', 'COA'],
  nonConformance: ['ncNo', 'NCR'],

  // Maintenance
  preventiveMaintenance: ['scheduleNo', 'PM'],
  breakdownMaintenance: ['ticketNo', 'BDT'],
  spareConsumption: ['entryNo', 'SPC'],
  maintenanceCost: ['entryNo', 'MCS'],

  // Finance
  journalVoucher: ['voucherNo', 'JV'],
  paymentVoucher: ['voucherNo', 'PV'],
  receiptVoucher: ['voucherNo', 'RV'],
  generalLedger: ['entryNo', 'GL'],
  expenseEntry: ['expenseNo', 'EXP'],
  budget: ['budgetNo', 'BDG'],

  // HR
  leaveRequest: ['requestNo', 'LVR'],
  shiftSchedule: ['scheduleNo', 'SFT'],
  payrollRun: ['runNo', 'PRN'],
  statutoryCompliance: ['entryNo', 'STC'],
};

/**
 * Marks the generated field on every submodule in the map. Fields are replaced
 * with copies so the original registry definitions are never mutated, and the
 * submodule remembers which field to fill (`autoNumberField`).
 */
function applyNumbering(modules) {
  const seen = new Set();
  for (const moduleDef of modules) {
    for (const submodule of moduleDef.submodules) {
      const entry = NUMBERING[submodule.key];
      if (!entry) continue;
      seen.add(submodule.key);
      const [fieldName, prefix, opts = {}] = entry;
      const index = submodule.fields.findIndex((field) => field.name === fieldName);
      if (index === -1) throw new Error(`numbering: "${submodule.key}" has no field "${fieldName}"`);
      submodule.fields[index] = {
        ...submodule.fields[index],
        autoNumber: { prefix, year: opts.year !== false },
      };
      submodule.autoNumberField = fieldName;
    }
  }
  for (const key of Object.keys(NUMBERING)) {
    if (!seen.has(key)) throw new Error(`numbering: unknown submodule "${key}"`);
  }
}

export { NUMBERING, applyNumbering };